#ifdef ARDUINO_ARCH_ESP32
#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>
#endif

// AI: below section was generated by an AI
// ESP32 AsyncTCP callbacks run on another task. ESP8266 callbacks share loop context.
class LightAlarmMutex {
#ifdef ARDUINO_ARCH_ESP32
  SemaphoreHandle_t _mutex = nullptr;
#endif
public:
  bool begin() {
#ifdef ARDUINO_ARCH_ESP32
    if (!_mutex) _mutex = xSemaphoreCreateMutex();
    return _mutex != nullptr;
#else
    return true;
#endif
  }
  bool take() {
#ifdef ARDUINO_ARCH_ESP32
    return _mutex && xSemaphoreTake(_mutex, pdMS_TO_TICKS(20)) == pdTRUE;
#else
    return true;
#endif
  }
  void give() {
#ifdef ARDUINO_ARCH_ESP32
    xSemaphoreGive(_mutex);
#endif
  }
};

class LightAlarmGuard {
  LightAlarmMutex& _mutex;
  bool _locked;
public:
  explicit LightAlarmGuard(LightAlarmMutex& mutex) : _mutex(mutex), _locked(mutex.take()) {}
  ~LightAlarmGuard() { if (_locked) _mutex.give(); }
  explicit operator bool() const { return _locked; }
  LightAlarmGuard(const LightAlarmGuard&) = delete;
  LightAlarmGuard& operator=(const LightAlarmGuard&) = delete;
};
